head.script:
scwin.trigger1_onclick = function(e) {
    scwin.bFormatter = function() {
        return [{
                'id': 'custombtn',
                'className': 'w2widget_btnCustom',
                'isCustom': true
            },
            {
                'id': 'custombtn2',
                'className': 'w2widget_btnCustom',
                'isCustom': true
            },
            {
                'id': 'custombtn3',
                'className': 'w2widget_btnCustom3',
                'isCustom': true
            },
            {
                'useDefault': 'maximize'
            },
            {
                'useDefault': 'close'
            }
        ];
    };
    scwin.mFormatter = function() {
        return {
            top: 2,
            bottom: 3,
            left: -1,
            right: 0
        };
    }
    count++;
    widgetContainer1.addWidgets({
        id: "widget" + count,
        title: "위젯" + count,
        src: "widget.xml",
        scope: true,
        x: 0,
        y: 0,
        unitWidth: 1,
        unitHeight: 1,
        buttonFormatter: scwin.bFormatter,
        maximizeFormatter: scwin.mFormatter
    });
};
scwin.bFormatter = function() {
    return [{
            'id': 'custombtn',
            'className': 'w2widget_btnCustom',
            'isCustom': true
        },
        {
            'id': 'custombtn2',
            'className': 'w2widget_btnCustom',
            'isCustom': true
        },
        {
            'id': 'custombtn3',
            'className': 'w2widget_btnCustom3',
            'isCustom': true
        },
        {
            'useDefault': 'maximize'
        },
        {
            'useDefault': 'close'
        }
    ];
};
scwin.mFormatter = function() {
    return {
        top: 2,
        bottom: 3,
        left: -1,
        right: 0
    };
}
scwin.widgetContainer_onclickcustombtn = function(widgetId, btnId) {
    btnVal = btnId;
    //alert("위젯아이디 : "+widgetId+"\n"+"버튼아이디 : "+btnId);
};
scwin.checktype = function() {
    return typeof WebSquare.wUnit.getObjById('widgetContainer1_widget1');
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 'addWidget'버튼을 클릭한다.
    //1. After running the sample file, click the 'addWidget' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    //Verify step 1. '위젯1'이 추가되어 보여진다.
    //1. 'Widget 1' is added and shown.
    WebSquare.wUnit.addCommand("assert", "scwin.checktype()", "object");
    //Test step 2. 위젯1 화면의 우측에 파란색 첫 번째 멀티창 이미지를 클릭한다.
    //2. On the right side of the Widget 1 screen, click the blue first multi-window image.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('widgetContainer1_widget1_title_custombtn').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 2. 알림창에 버튼아이디가 'custombtn'이 보여진다.
    //2. In the notification window, the button ID 'custombtn' is displayed.
    WebSquare.wUnit.addCommand("assert", "btnVal", "custombtn");
    //Test step 3. 위젯1 화면의 우측에 파란색 두 번째 멀티창 이미지를 클릭한다.
    //3. On the right side of the Widget 1 screen, click the blue second multi-window image.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('widgetContainer1_widget1_title_custombtn2').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 3. 알림창에 버튼아이디가 'custombtn2'이 보여진다.(이전에는 'custombtn'이 보여짐)
    //3. The button ID 'custombtn2' is displayed in the notification window (previously 'custombtn' is displayed)
    WebSquare.wUnit.addCommand("assert", "btnVal", "custombtn2");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.count = 0;
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 06-Feb-2018
    window.btnVal = "";
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
